DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `quantity` int NOT NULL,
  `status` varchar(255) DEFAULT NULL,
  `totalPrice` decimal(38,2) DEFAULT NULL,
  `delivery_agent_id` bigint DEFAULT NULL,
  `product_id` bigint NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `delivery_address_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKhbvspo3vxp3o28v78pwd4my6l` (`delivery_address_id`),
  KEY `FKkp5k52qtiygd8jkag4hayd0qg` (`product_id`),
  KEY `FK32ql8ubntj5uh44ph9659tiih` (`user_id`),
